<?php
declare(strict_types=1);
namespace Namira;
use PDO;
final class MartyrCatalogWeb {
    public static function handles(string $action):bool{return in_array($action,['martyr-axis-save','martyr-term-save','martyr-term-merge','martyr-term-undo'],true);}
    public static function action(PDO $db,string $action):never {
        $actor=Permissions::require($db,'taxonomy.manage');AdminPanel::boot($db,$actor);$manager=new MartyrCatalogManager($db,$actor);$axis=Security::text($_POST,'taxonomy',40,false)?:Security::text($_POST,'axis_key',40,false);$term=0;
        try{switch($action){case 'martyr-axis-save':$axis=$manager->axis($_POST);break;case 'martyr-term-save':$term=$manager->term($_POST);if(str_contains($_SERVER['HTTP_ACCEPT']??'','application/json')){header('Content-Type: application/json; charset=utf-8');header('Cache-Control: private, no-store');echo json_encode(['id'=>$term,'label'=>Db::query($db,'SELECT title FROM protocol_terms WHERE id=?',[$term])->fetchColumn()]);exit;}break;case 'martyr-term-merge':$manager->merge($_POST);break;case 'martyr-term-undo':$manager->undo($_POST);break;}$_SESSION['flash']='دسته‌بندی ذخیره شد؛ شناسه‌ها و روابط قبلی حفظ شدند.';}catch(HttpError $e){if(str_contains($_SERVER['HTTP_ACCEPT']??'','application/json'))throw $e;$_SESSION['catalog_feedback']=['input'=>$_POST,'errors'=>['form'=>$e->getMessage()]];}
        redirect('admin',['tab'=>'categories']+($axis?['axis'=>$axis]:[])+($term?['term'=>$term]:[]));
    }
    public static function options(PDO $db):never {
        $actor=Security::user($db);if(!Permissions::allows($db,$actor,'martyrs.edit')&&!Permissions::allows($db,$actor,'taxonomy.view'))throw new HttpError(403,'مجوز مشاهده فرهنگ جغرافیا ندارید.');$level=Security::text($_GET,'level',10);if(!in_array($level,['country','province','county','city'],true))throw new HttpError(422,'سطح مکان معتبر نیست.');$parent=(int)($_GET['parent']??0);$selected=(int)($_GET['selected']??0);$expected=['province'=>'country','county'=>'province','city'=>'county'][$level]??null;if($expected&&(!$parent||!Db::query($db,'SELECT id FROM protocol_terms WHERE id=? AND taxonomy=?',[$parent,$expected])->fetchColumn()))throw new HttpError(422,'والد جغرافیا معتبر نیست.');
        $rows=Db::query($db,'SELECT id,title,parent_id,active FROM protocol_terms WHERE taxonomy=? AND (active=1 OR id=?)'.($expected?' AND parent_id=?':'').' ORDER BY sort_order,title',[$level,$selected,...($expected?[$parent]:[])])->fetchAll();header('Content-Type: application/json; charset=utf-8');header('Cache-Control: private, no-store');echo json_encode($rows,JSON_UNESCAPED_UNICODE);exit;
    }
    public static function show(PDO $db,array $actor):void {
        Permissions::require($db,'taxonomy.view');$axis=Security::text($_GET,'axis',40,false);$axes=MartyrCatalog::axes($db);$selected=null;foreach($axes as &$a){$a['term_count']=(int)Db::query($db,'SELECT COUNT(*) FROM protocol_terms WHERE taxonomy=?',[$a['axis_key']])->fetchColumn();$a['person_count']=(int)Db::query($db,'SELECT COUNT(DISTINCT martyr_id) FROM martyr_public_terms WHERE axis_key=?',[$a['axis_key']])->fetchColumn();if($a['axis_key']===$axis)$selected=$a;}unset($a);$geographic=in_array($axis,['country','province','county','city'],true);if($axis&&!$selected&&!$geographic)throw new HttpError(404,'محور پیدا نشد.');if($geographic)$selected=['axis_key'=>$axis,'title'=>ProtocolSpec::taxonomies()[$axis]];
        $terms=['items'=>[],'count'=>0,'page'=>1,'pages'=>1,'per'=>25];$editing=null;$parents=[];$redirects=[];if($axis){$where='taxonomy=?';$args=[$axis];$q=Security::text($_GET,'q',150,false);if($q!==''){$where.=' AND title LIKE ?';$args[]='%'.$q.'%';}$terms=AdminQueries::paginate($db,'SELECT *','FROM protocol_terms',$where,$args,['order'=>'sort_order,title,id'],$_GET);foreach($terms['items'] as &$t)$t['used_count']=MartyrCatalog::selectedCount($db,(int)$t['id']);unset($t);$termId=(int)($_GET['term']??0);if($termId)$editing=Db::query($db,'SELECT * FROM protocol_terms WHERE id=? AND taxonomy=?',[$termId,$axis])->fetch();$parentTax=['province'=>'country','county'=>'province','city'=>'county','organization_subunit'=>'organization'][$axis]??$axis;$parents=Db::query($db,'SELECT id,title,parent_id FROM protocol_terms WHERE taxonomy=? ORDER BY title',[$parentTax])->fetchAll();$redirects=Db::query($db,'SELECT r.*,a.title AS source_title,b.title AS target_title FROM martyr_term_redirects r JOIN protocol_terms a ON a.id=r.source_term_id JOIN protocol_terms b ON b.id=r.target_term_id WHERE a.taxonomy=? AND r.active=1',[$axis])->fetchAll();}
        $feedback=$_SESSION['catalog_feedback']??[];unset($_SESSION['catalog_feedback']);$old=$feedback['input']??null;$errors=$feedback['errors']??[];view('martyr-catalog',compact('db','actor','axes','selected','axis','terms','editing','parents','geographic','redirects','old','errors'));
    }
}
